 async function loadCurrentProfile(){const {data,error}=await supabase.from('user_profiles').select('user_id,full_name,role,is_active').eq('user_id',session.user.id).maybeSingle();if(error){setMsg(`User profile could not be loaded: ${error.message}`);return}if(!data||data.is_active===false){setMsg('This account has no active school profile. Contact the administrator.');await supabase.auth.signOut();return}setCurrentProfile(data)}
 async function loadProfiles(){setProfilesBusy(true);const {data,error}=await supabase.from('user_profiles').select('user_id,full_name,role,is_active').order('full_name');setProfilesBusy(false);if(error){setMsg(error.message);return}setProfiles(data||[])}
 async function addProfile(e){e.preventDefault();if(!newProfile.user_id.trim()||!newProfile.full_name.trim()){setMsg('Enter the existing Supabase Auth User ID and full name.');return}setProfileSaving(true);const payload={user_id:newProfile.user_id.trim(),full_name:newProfile.full_name.trim(),role:newProfile.role,is_active:newProfile.is_active};const {error}=await supabase.from('user_profiles').insert(payload);setProfileSaving(false);if(error){setMsg(error.message);return}await writeAudit('create','user_profiles',payload.user_id,{role:payload.role});setNewProfile({user_id:'',full_name:'',role:'teacher',is_active:true});setMsg('User profile added.');loadProfiles()}
 async function updateProfileRole(userId,patch){if(userId===session?.user?.id&&(patch.role&&patch.role!=='admin'||patch.is_active===false)){setMsg('You cannot change or deactivate your own administrator profile.');return}const target=profiles.find(x=>x.user_id===userId);if(target?.role==='admin'&&(patch.role==='teacher'||patch.is_active===false)&&profiles.filter(x=>x.role==='admin'&&x.is_active).length<=1){setMsg('At least one active administrator must remain.');return}const {error}=await supabase.from('user_profiles').update(patch).eq('user_id',userId);if(error){setMsg(error.message);return}await writeAudit('update','user_profiles',userId,patch);setProfiles(old=>old.map(x=>x.user_id===userId?{...x,...patch}:x));setMsg('User profile updated.')}
 async function writeAudit(action,tableName=null,recordId=null,details={}){try{const {data}=await supabase.auth.getUser();await supabase.from('audit_logs').insert({actor_user_id:data?.user?.id||null,action,table_name:tableName,record_id:recordId,details});}catch(e){console.warn('Activity log could not be saved:',e.message)}}
