 async function saveGeneric(e){e.preventDefault();const cfg=configs[page];let payload={...form};if(page==='exams')payload.session_id=activeSession?.id;if(page==='expenses'&&!payload.expense_category_id){setMsg('প্রথমে ব্যয়ের বিভাগ তৈরি করুন।');return}const query=supabase.from(cfg.table).insert(payload);const {data,error}=page==='expenses'?await query.select('id,voucher_number,expense_category_id,expense_date,amount,payment_method,description,payee_name').single():await query;if(error){setMsg(error.message);return}await writeAudit('create',cfg.table,data?.id||null,{record:page});if(page==='expenses'){const cat=expenseCategories.find(x=>x.id===data.expense_category_id);const {error:ledgerError}=await supabase.from('account_entries').insert({entry_type:'expense',source_type:'expense',source_id:data.id,entry_date:data.expense_date,category:cat?.category_name||'Expense',amount:Number(data.amount),payment_method:data.payment_method,reference_number:data.voucher_number,description:data.description||data.payee_name||'School expense'});if(ledgerError){setMsg(`Expense saved, but Accounts entry failed: ${ledgerError.message}. Please reconcile before entering it again.`);loadConfig(page);return}}setMsg('রেকর্ড সংরক্ষিত হয়েছে।');setForm({});loadConfig(page);if(page==='teachers')loadBase();if(page==='expenses')loadAccounts()}
