 async function saveSalary(e){
  e.preventDefault();if(!salaryTeacher){setMsg('Select a teacher.');return}
  const fixed=Number(salaryFixed),deduction=Number(salaryDeduction||0),bonus=Number(salaryBonus||0),amount=fixed-deduction+bonus;
  if(fixed<0||deduction<0||bonus<0||amount<=0){setMsg('Check salary, deduction and bonus. Net salary must be greater than zero.');return}
  const monthDate=`${salaryMonth}-01`;
  setSalarySaving(true);
  try{
   const {data:existing,error:checkError}=await supabase.from('teacher_salary_payments').select('id').eq('teacher_id',salaryTeacher).eq('salary_month',monthDate).limit(1);
   if(checkError)throw checkError;
   if(existing?.length){setMsg('Salary for this teacher and month is already recorded. Check the salary register to avoid duplicate payment.');return}
   const {data,error}=await supabase.from('teacher_salary_payments').insert({teacher_id:salaryTeacher,salary_month:monthDate,payment_date:salaryDate,fixed_salary_snapshot:fixed,deduction_amount:deduction,bonus_amount:bonus,amount_paid:amount,payment_method:salaryMethod,reason:salaryReason||null}).select('id,teacher_id,salary_month,payment_date,amount_paid,payment_method').single();
   if(error)throw error;
   const teacher=salaryTeachers.find(x=>x.id===salaryTeacher),voucher=`SAL-${data.id.slice(0,8).toUpperCase()}`;
   const {error:ledgerError}=await supabase.from('account_entries').insert({entry_type:'expense',source_type:'teacher_salary_payment',source_id:data.id,entry_date:data.payment_date,category:'Teacher Salary',amount:amount,payment_method:salaryMethod,reference_number:voucher,description:`Salary — ${teacher?.teacher_name||'Teacher'} — ${salaryMonth}`});
   if(ledgerError){setMsg(`Salary saved (${voucher}), but Accounts entry failed: ${ledgerError.message}. Please reconcile before retrying.`);await loadSalaryData();return}
   setMsg(`Salary payment recorded. Voucher: ${voucher}`);setSalaryReason('');setSalaryDeduction('0');setSalaryBonus('0');await loadSalaryData();
  }catch(err){setMsg(err.message)}finally{setSalarySaving(false)}
 }
